folder=R/'client/assets/v70/redrawn-v61';folder.mkdir(parents=True,exist_ok=True)
manifest=[];mapped={}
for r in remaining:
 name=r['name'];slug=re.sub(r'[^a-z0-9]+','-',name.lower()).strip('-')
 svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">'+A[name]+'</svg>'
 file=folder/f'{slug}.svg';file.write_text(svg,encoding='utf-8')
 rel=file.relative_to(R).as_posix();hash=hashlib.sha256(svg.encode()).hexdigest()
 manifest.append(dict(name=name,id=r['id'],path=rel,sha256=hash,art_mode='bespoke-silhouette',source='subject-drawn-v70'))
 mapped[name.lower()]=svg
(R/'shared/v70-approved.json').write_text(json.dumps({'version':70,'new_items':[],'redrawn_v61':manifest,'remaining_v61_motif_composites':0},indent=2)+'\n')
